#include <cmath>
#include <type_traits>

template <typename T, std::enable_if_t<std::is_integral_v<T>, int> = 0>
T twice(T value)
{
    return value * 2;
}

template <typename T, std::enable_if_t<std::is_floating_point_v<T>, int> = 0>
T twice(T value)
{
    return std::round(value * static_cast<T>(2.0));
}

unitTests:
template <typename T> concept CanTwice = requires(T t) { twice(t); };
static_assert(CanTwice<int> && CanTwice<long long> && CanTwice<double> && CanTwice<float>);
static_assert(!CanTwice<std::string> && !CanTwice<int*>, "other types should have no matching overload");
static_assert(std::is_same_v<decltype(twice(1.5f)), float> && std::is_same_v<decltype(twice(3)), int>);

TEST("integers") { CHECK_EQ(twice(21), 42); CHECK_EQ(twice(-4LL), -8LL); }
TEST("floating point is rounded") { CHECK_NEAR(twice(1.3), 3.0, 1e-12); CHECK_NEAR(twice(1.2), 2.0, 1e-12); CHECK_NEAR(twice(2.5f), 5.0, 1e-6); }

